# MAGIC %md
# MAGIC ## SPARQL

# COMMAND ----------

APP_NAME = "ontobricks-08x"
TARGET_DOMAIN = "CustomerJourney"
DOMAIN_VERSION = "1"

# COMMAND ----------

import requests
import pandas as pd
from databricks.sdk import WorkspaceClient

# 認証
w = WorkspaceClient()
app = w.apps.get(APP_NAME)
app_url = app.url.rstrip("/")

notebook_token = (
    dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
)

r = requests.post(
    f"{w.config.host.rstrip('/')}/oidc/v1/token",
    data={
        "grant_type": "urn:ietf:params:oauth:grant-type:token-exchange",
        "subject_token": notebook_token,
        "subject_token_type": "urn:databricks:params:oauth:token-type:personal-access-token",
        "requested_token_type": "urn:ietf:params:oauth:token-type:access_token",
        "scope": "all-apis",
        "audience": app.oauth2_app_client_id,
    },
    timeout=30,
)
r.raise_for_status()

session = requests.Session()
session.headers["Authorization"] = f"Bearer {r.json()['access_token']}"


# 共通のAPI呼び出し
def api(method, path, **kwargs):
    headers = {}
    if method == "POST":
        csrf = session.cookies.get("csrf_token")
        if not csrf:
            raise RuntimeError("CSRFトークンを取得できませんでした")
        headers["X-CSRF-Token"] = csrf
    response = session.request(
        method,
        f"{app_url}{path}",
        headers=headers,
        timeout=120,
        **kwargs,
    )
    if not response.ok:
        raise RuntimeError(f"{path}: HTTP {response.status_code}\n{response.text}")
    data = response.json()
    if data.get("success") is False:
        raise RuntimeError(f"{path}: {data}")
    return data


# ドメイン名の解決とセッション初期化
domains = api("GET", "/domain/list-projects").get("domains", [])
domain_name = next(
    (name for name in domains if name.casefold() == TARGET_DOMAIN.casefold()),
    None,
)

if domain_name is None:
    raise ValueError(f"{TARGET_DOMAIN}が見つかりません。候補: {domains}")

api(
    "POST",
    "/domain/load-from-uc",
    json={
        "domain": domain_name,
        "version": DOMAIN_VERSION,
    },
)

print(f"対象: {domain_name} / V{DOMAIN_VERSION}")

# COMMAND ----------

def execute_sparql(query, limit=100):
    result = api(
        "POST",
        "/dtwin/execute",
        json={
            "query": query,
            "limit": limit,
        },
    )

    rows = result.get("results", [])
    print(f"取得件数: {len(rows)}")

    if rows:
        display(pd.DataFrame(rows))
    else:
        print("結果は0行です")

# COMMAND ----------

# 1. 10 人の顧客
execute_sparql(
    """
    PREFIX ont: <https://databricks-ontology.com/CustomerJourney#>
    PREFIX customer: <https://databricks-ontology.com/CustomerJourney/property/Customer/>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

    SELECT ?customer ?customerId ?label ?segment ?isActive
    WHERE {
        ?customer a ont:Customer .
        ?customer customer:customerId ?customerId .
        ?customer rdfs:label ?label .
        ?customer customer:segment ?segment .
        ?customer customer:isActive ?isActive .
    }
    LIMIT 10
    """,
    limit=10,
)

# COMMAND ----------

# 2. James Martin の契約：期待値 CON0000184
execute_sparql(
    """
    PREFIX ont: <https://databricks-ontology.com/CustomerJourney#>
    PREFIX contract: <https://databricks-ontology.com/CustomerJourney/property/Contract/>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

    SELECT
        ?contract
        ?contractId
        ?energyType
        ?startDate
        ?endDate
        ?status
        ?monthlyFee
        ?paymentMethod
        ?autoRenewal
    WHERE {
        ?customer a ont:Customer .
        ?customer rdfs:label "James Martin" .
        ?customer ont:hasContract ?contract .

        ?contract a ont:Contract .
        ?contract contract:contract_id ?contractId .
        ?contract contract:energy_type ?energyType .
        ?contract contract:start_date ?startDate .
        ?contract contract:end_date ?endDate .
        ?contract contract:status ?status .
        ?contract contract:monthly_fee ?monthlyFee .
        ?contract contract:payment_method ?paymentMethod .
        ?contract contract:auto_renewal ?autoRenewal .
    }
    """,
    limit=10,
)

# COMMAND ----------

# 3. James Martinの請求書を表示
execute_sparql(
    """
    PREFIX ont: <https://databricks-ontology.com/CustomerJourney#>
    PREFIX customer: <https://databricks-ontology.com/CustomerJourney/property/Customer/>
    PREFIX contract: <https://databricks-ontology.com/CustomerJourney/property/Contract/>
    PREFIX invoice: <https://databricks-ontology.com/CustomerJourney/property/Invoice/>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

    SELECT
        ?customerId
        ?contractId
        ?invoice
        ?invoiceId
        ?invoiceStatus
        ?amountTtc
    WHERE {
        ?customer a ont:Customer .
        ?customer customer:customer_id ?customerId .
        ?customer rdfs:label "James Martin" .
        ?customer ont:hasContract ?contract .

        ?contract a ont:Contract .
        ?contract contract:contract_id ?contractId .
        ?contract ont:generatesInvoice ?invoice .

        ?invoice a ont:Invoice .
        ?invoice invoice:invoice_id ?invoiceId .
        ?invoice invoice:status ?invoiceStatus .
        ?invoice invoice:amount_ttc ?amountTtc .
    }
    """,
    limit=100,
)

